import { withPayload } from '@payloadcms/next/withPayload'

// Security headers applied to every response. We deliberately do not send a
// Content-Security-Policy header here because the Payload admin (`/admin`)
// uses inline scripts/styles generated by React Server Components and a strict
// CSP would break it. If a tighter policy is needed later, scope it to
// frontend routes only via the `source` matcher.
const securityHeaders = [
  { key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains; preload' },
  { key: 'X-Content-Type-Options', value: 'nosniff' },
  { key: 'X-Frame-Options', value: 'SAMEORIGIN' },
  { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
  { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=(), interest-cohort=()' },
  { key: 'X-DNS-Prefetch-Control', value: 'on' },
]

/** @type {import('next').NextConfig} */
const nextConfig = {
  experimental: {
    // The Payload admin computes form state on the server: every keystroke,
    // and every "add row" on an array field, POSTs the *entire* serialized
    // form state back through a Next Server Action. That payload runs roughly
    // 2.5–3x the size of the document itself, because form state carries both
    // `value` and `initialValue` (plus validation metadata) for every field,
    // and rich text fields carry their whole Lexical tree twice.
    //
    // Next caps Server Action bodies at 1 MB by default. Past that, the action
    // fails with a 413 — and Payload's getFormState swallows the error and
    // returns no state, so a newly added array row never receives its
    // server-rendered fields and shimmers forever with no error shown. A large
    // Case File dossier (long overview plus a full timeline, documents, audits,
    // and coverage) crosses 1 MB of form state at roughly 370 KB of content.
    //
    // 4 MB leaves headroom for the largest dossiers; Workers accept far more.
    serverActions: {
      bodySizeLimit: '4mb',
    },
  },
  // These ship a separate build for Cloudflare's workerd runtime, which is only
  // picked up if Next leaves them unbundled.
  // https://opennext.js.org/cloudflare/howtos/workerd
  serverExternalPackages: ['jose', 'pg-cloudflare'],
  webpack: (webpackConfig) => {
    webpackConfig.resolve.extensionAlias = {
      '.cjs': ['.cts', '.cjs'],
      '.js': ['.ts', '.tsx', '.js', '.jsx'],
      '.mjs': ['.mts', '.mjs'],
    }
    return webpackConfig
  },
  // cms.transformidablethinking.com and transformidable.net are admin
  // addresses, not the public site: send anything that isn't the admin, its
  // API, or a static file to the admin login.
  async redirects() {
    return [
      {
        source: '/:path((?!admin|api|_next)(?!.*\\.\\w+$).*)',
        has: [{ type: 'host', value: '(?:cms\\..*|(?:www\\.)?(?:transformidable\\.net|jlynne\\.io))' }],
        destination: '/admin',
        permanent: false,
      },
      // The Academy's first Course 1 was replaced by the Boards & Councils
      // briefing.
      {
        source: '/academy/courses/ai-explained',
        destination: '/academy/courses/ai-governance-for-boards-and-councils',
        permanent: true,
      },
      // The certificate is not advertised while its curriculum and
      // requirements are settled. Temporary, so the page can return.
      {
        source: '/academy/foundation-certificate',
        destination: '/academy',
        permanent: false,
      },
    ]
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: securityHeaders,
      },
    ]
  },
}

export default withPayload(nextConfig)
